import csv
import io


def parse_csv(raw_csv: str):
    expected_width = 10

    try:
        parsed_rows = list(
            csv.reader(
                io.StringIO(raw_csv, newline=""),
                delimiter=",",
                quotechar='"',
                doublequote=True,
                strict=False,
            )
        )
    except csv.Error:
        parsed_rows = []

    header_index = next(
        (i for i, row in enumerate(parsed_rows) if len(row) == expected_width),
        None,
    )

    if header_index is None:
        header_index = next(
            (i for i, row in enumerate(parsed_rows) if row),
            None,
        )

    if header_index is None:
        return {"columns": [], "rows": []}

    columns = list(parsed_rows[header_index])
    if len(columns) < expected_width:
        columns.extend("" for _ in range(expected_width - len(columns)))

    data_rows = parsed_rows[header_index + 1 :]
    widest_row = max((len(row) for row in data_rows), default=len(columns))

    while len(columns) < widest_row:
        columns.append(f"Unnamed: {len(columns) + 1}")

    normalized_rows = [
        list(row) + [""] * (len(columns) - len(row))
        for row in data_rows
    ]

    return {"columns": columns, "rows": normalized_rows}
